import logging

import torch
import triton
import triton.language as tl

from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

_TINY = tl.constexpr(1e-30)
_EPS = tl.constexpr(1e-6)


@triton.jit
def _elem(M, rr, cc, i, j):
    # scalar M[i, j] extracted from a register tile via masked reduction
    return tl.sum(tl.where((rr == i) & (cc == j), M, 0.0))


@triton.jit
def _house_apply(H, Q, v):
    # H <- (I - 2 v v^T) H (I - 2 v v^T);  Q <- Q (I - 2 v v^T)
    w = tl.sum(v[:, None] * H, axis=0)
    H = H - 2.0 * v[:, None] * w[None, :]
    u = tl.sum(H * v[None, :], axis=1)
    H = H - 2.0 * u[:, None] * v[None, :]
    qv = tl.sum(Q * v[None, :], axis=1)
    Q = Q - 2.0 * qv[:, None] * v[None, :]
    return H, Q


@triton.jit
def _cdiv(ar, ai, br, bi):
    d = br * br + bi * bi
    d = tl.where(d > _TINY, d, _TINY)
    return (ar * br + ai * bi) / d, (ai * br - ar * bi) / d


@libentry()
@triton.jit
def _eig_kernel(A, LR, LI, VR, VI, N, MAXIT, BLOCK: tl.constexpr):
    """Eigendecomposition of one real square matrix per program.

    The whole N x N matrix lives in a BLOCK x BLOCK register tile. Real dense
    linear algebra is done entirely in-kernel:
      1. Householder reduction to upper Hessenberg form (Q accumulated).
      2. Francis double-shift QR -> real Schur form T (Q updated).
      3. Eigenvalues from the 1x1 / 2x2 diagonal blocks of T.
      4. Complex eigenvectors of T by back-substitution, then V = Q @ V_T.
    Reflector vectors are zero outside their support, so a full-tile rank-1
    update equals the exact similarity transform on the active rows/columns.
    """
    pid = tl.program_id(0)
    base = pid * N * N
    idx = tl.arange(0, BLOCK)
    rr = idx[:, None]
    cc = idx[None, :]
    in_mask = (rr < N) & (cc < N)

    H = tl.load(A + base + rr * N + cc, mask=in_mask, other=0.0).to(tl.float32)
    Q = tl.where(rr == cc, 1.0, 0.0).to(tl.float32)

    # ---- 1. Hessenberg reduction ----
    k = 0
    while k < N - 2:
        colk = tl.sum(tl.where(cc == k, H, 0.0), axis=1)  # H[:, k]
        support = (idx >= k + 1) & (idx < N)
        xv = tl.where(support, colk, 0.0)
        nrm = tl.sqrt(tl.sum(xv * xv))
        xp = tl.sum(tl.where(idx == k + 1, xv, 0.0))
        alpha = -tl.where(xp >= 0.0, 1.0, -1.0) * nrm
        v = xv - tl.where(idx == k + 1, alpha, 0.0)
        vn = tl.sqrt(tl.sum(v * v))
        v = tl.where(nrm > _TINY, v / tl.where(vn > _TINY, vn, 1.0), 0.0)
        H, Q = _house_apply(H, Q, v)
        k += 1

    # ---- 2. Francis double-shift QR ----
    p = N
    it = 0
    while (p > 2) and (it < MAXIT):
        it += 1
        # deflate tiny subdiagonals in the active block [0, p)
        i = 1
        while i < p:
            sub = _elem(H, rr, cc, i, i - 1)
            dp = _elem(H, rr, cc, i - 1, i - 1)
            dc = _elem(H, rr, cc, i, i)
            small = tl.abs(sub) <= _EPS * (tl.abs(dp) + tl.abs(dc) + _TINY)
            H = tl.where((rr == i) & (cc == i - 1) & small, 0.0, H)
            i += 1

        # l = start of trailing unreduced block ending at p-1
        ll = p - 1
        cont = ll > 0
        while cont:
            if _elem(H, rr, cc, ll, ll - 1) != 0.0:
                ll -= 1
                cont = ll > 0
            else:
                cont = False

        if ll >= p - 2:
            p = ll  # trailing 1x1 / 2x2 block isolated -> deflate
        else:
            m = p - 1
            hmm = _elem(H, rr, cc, m, m)
            hm1m1 = _elem(H, rr, cc, m - 1, m - 1)
            hm1m = _elem(H, rr, cc, m - 1, m)
            hmm1 = _elem(H, rr, cc, m, m - 1)
            s = hm1m1 + hmm
            t = hm1m1 * hmm - hm1m * hmm1
            hll = _elem(H, rr, cc, ll, ll)
            hll1 = _elem(H, rr, cc, ll, ll + 1)
            hl1l = _elem(H, rr, cc, ll + 1, ll)
            hl1l1 = _elem(H, rr, cc, ll + 1, ll + 1)
            hl2l1 = _elem(H, rr, cc, ll + 2, ll + 1)
            x = hll * hll + hll1 * hl1l - s * hll + t
            y = hl1l * (hll + hl1l1 - s)
            z = hl1l * hl2l1

            kk = ll
            while kk < m - 1:
                xv = (
                    tl.where(idx == kk, x, 0.0)
                    + tl.where(idx == kk + 1, y, 0.0)
                    + tl.where(idx == kk + 2, z, 0.0)
                )
                nrm = tl.sqrt(tl.sum(xv * xv))
                xp = tl.sum(tl.where(idx == kk, xv, 0.0))
                alpha = -tl.where(xp >= 0.0, 1.0, -1.0) * nrm
                v = xv - tl.where(idx == kk, alpha, 0.0)
                vn = tl.sqrt(tl.sum(v * v))
                v = tl.where(nrm > _TINY, v / tl.where(vn > _TINY, vn, 1.0), 0.0)
                H, Q = _house_apply(H, Q, v)
                x = _elem(H, rr, cc, kk + 1, kk)
                y = _elem(H, rr, cc, kk + 2, kk)
                z = tl.where(kk + 3 <= m, _elem(H, rr, cc, kk + 3, kk), 0.0)
                kk += 1

            # trailing 2x2 Givens on (x, y)
            xy = tl.where(idx == m - 1, x, 0.0) + tl.where(idx == m, y, 0.0)
            nrm = tl.sqrt(tl.sum(xy * xy))
            xp = tl.sum(tl.where(idx == m - 1, xy, 0.0))
            alpha = -tl.where(xp >= 0.0, 1.0, -1.0) * nrm
            v = xy - tl.where(idx == m - 1, alpha, 0.0)
            vn = tl.sqrt(tl.sum(v * v))
            v = tl.where(nrm > _TINY, v / tl.where(vn > _TINY, vn, 1.0), 0.0)
            H, Q = _house_apply(H, Q, v)

    # ---- 3. eigenvalues + block structure from Schur form ----
    # blk[i] == 1 marks the top row of a 2x2 complex block (i, i+1)
    lr = tl.zeros((BLOCK,), dtype=tl.float32)
    li = tl.zeros((BLOCK,), dtype=tl.float32)
    blk = tl.zeros((BLOCK,), dtype=tl.int32)
    j = 0
    while j < N:
        sub = tl.where(j < N - 1, _elem(H, rr, cc, j + 1, j), 0.0)
        dj = _elem(H, rr, cc, j, j)
        dj1 = tl.where(j < N - 1, _elem(H, rr, cc, j + 1, j + 1), 0.0)
        is2 = (j < N - 1) & (tl.abs(sub) > _EPS * (tl.abs(dj) + tl.abs(dj1) + _TINY))
        if is2:
            a = dj
            b = _elem(H, rr, cc, j, j + 1)
            c = sub
            d = dj1
            tr = a + d
            det = a * d - b * c
            disc = tr * tr - 4.0 * det
            sq = tl.sqrt(tl.abs(disc))
            re = tr * 0.5
            pos = disc >= 0.0
            r0 = tl.where(pos, (tr + sq) * 0.5, re)
            r1 = tl.where(pos, (tr - sq) * 0.5, re)
            im0 = tl.where(pos, 0.0, sq * 0.5)
            lr = lr + tl.where(idx == j, r0, 0.0) + tl.where(idx == j + 1, r1, 0.0)
            li = li + tl.where(idx == j, im0, 0.0) + tl.where(idx == j + 1, -im0, 0.0)
            blk = blk + tl.where(idx == j, 1, 0)
            j += 2
        else:
            lr = lr + tl.where(idx == j, dj, 0.0)
            j += 1

    # store eigenvalues
    row = idx
    tl.store(LR + pid * N + row, lr, mask=row < N)
    tl.store(LI + pid * N + row, li, mask=row < N)

    # ---- 4. eigenvectors of T by complex back-substitution, then V = Q @ x ----
    j = 0
    while j < N:
        L_r = tl.sum(tl.where(idx == j, lr, 0.0))
        L_i = tl.sum(tl.where(idx == j, li, 0.0))
        xr = tl.zeros((BLOCK,), dtype=tl.float32)
        xi = tl.zeros((BLOCK,), dtype=tl.float32)

        # seed depending on whether j closes a 2x2 block or is a 1x1 block
        prev_blk = tl.where(j > 0, tl.sum(tl.where(idx == j - 1, blk, 0)), 0)
        this_blk = tl.sum(tl.where(idx == j, blk, 0))
        if prev_blk == 1:  # j is the bottom (second) index of block (j-1, j)
            b = j - 1
            tbb1 = _elem(H, rr, cc, b, b + 1)
            tbb = _elem(H, rr, cc, b, b)
            xr = (
                xr
                + tl.where(idx == b, tbb1, 0.0)
                + tl.where(idx == b + 1, L_r - tbb, 0.0)
            )
            xi = xi + tl.where(idx == b + 1, L_i, 0.0)
            top = b - 1
        elif this_blk == 1:  # j is the top (first) index of block (j, j+1)
            tjj1 = _elem(H, rr, cc, j, j + 1)
            tjj = _elem(H, rr, cc, j, j)
            xr = (
                xr
                + tl.where(idx == j, tjj1, 0.0)
                + tl.where(idx == j + 1, L_r - tjj, 0.0)
            )
            xi = xi + tl.where(idx == j + 1, L_i, 0.0)
            top = j - 1
        else:
            xr = xr + tl.where(idx == j, 1.0, 0.0)
            top = j - 1

        i = top
        while i >= 0:
            rowi = tl.sum(tl.where(rr == i, H, 0.0), axis=0)  # T[i, :]
            colmask = idx > i
            r_r = -tl.sum(tl.where(colmask, rowi * xr, 0.0))
            r_i = -tl.sum(tl.where(colmask, rowi * xi, 0.0))
            prev = tl.where(i > 0, tl.sum(tl.where(idx == i - 1, blk, 0)), 0)
            if prev == 1:  # 2x2 diagonal block (i-1, i)
                rowim1 = tl.sum(tl.where(rr == i - 1, H, 0.0), axis=0)
                r0r = -tl.sum(tl.where(colmask, rowim1 * xr, 0.0))
                r0i = -tl.sum(tl.where(colmask, rowim1 * xi, 0.0))
                a00 = _elem(H, rr, cc, i - 1, i - 1) - L_r
                a01 = _elem(H, rr, cc, i - 1, i)
                a10 = _elem(H, rr, cc, i, i - 1)
                a11 = _elem(H, rr, cc, i, i) - L_r
                # complex 2x2 solve: A [x0;x1] = [r0;r1], A diagonal has -L_i imag
                detr = (a00 * a11 - (-L_i) * (-L_i)) - a01 * a10
                deti = a00 * (-L_i) + (-L_i) * a11
                # numerator0 = r0*a11c - a01*r1  (a11c = a11 + i*(-L_i))
                n0r = r0r * a11 - r0i * (-L_i) - a01 * r_r
                n0i = r0r * (-L_i) + r0i * a11 - a01 * r_i
                n1r = a00 * r_r - r_i * (-L_i) - a10 * r0r
                n1i = a00 * r_i + r_r * (-L_i) - a10 * r0i
                x0r, x0i = _cdiv(n0r, n0i, detr, deti)
                x1r, x1i = _cdiv(n1r, n1i, detr, deti)
                xr = (
                    xr + tl.where(idx == i - 1, x0r, 0.0) + tl.where(idx == i, x1r, 0.0)
                )
                xi = (
                    xi + tl.where(idx == i - 1, x0i, 0.0) + tl.where(idx == i, x1i, 0.0)
                )
                i -= 2
            else:  # 1x1 block
                dr = _elem(H, rr, cc, i, i) - L_r
                di = -L_i
                xvr, xvi = _cdiv(r_r, r_i, dr, di)
                xr = xr + tl.where(idx == i, xvr, 0.0)
                xi = xi + tl.where(idx == i, xvi, 0.0)
                i -= 1

        # V[:, j] = Q @ x
        vr = tl.sum(Q * xr[None, :], axis=1)
        vi = tl.sum(Q * xi[None, :], axis=1)
        nrm = tl.sqrt(tl.sum(vr * vr + vi * vi))
        nrm = tl.where(nrm > _TINY, nrm, 1.0)
        vr = vr / nrm
        vi = vi / nrm
        tl.store(VR + base + row * N + j, vr, mask=row < N)
        tl.store(VI + base + row * N + j, vi, mask=row < N)
        j += 1


def linalg_eig(A):
    logger.debug("GEMS LINALG_EIG")
    if A.dim() < 2 or A.shape[-1] != A.shape[-2]:
        raise ValueError("linalg.eig expects batches of square matrices")

    if A.is_complex():
        raise NotImplementedError("FlagGems linalg.eig supports real inputs only")

    # Only float32 is supported due to QR iteration precision requirements
    if A.dtype != torch.float32:
        raise NotImplementedError("FlagGems linalg.eig currently supports float32 only")

    n = A.shape[-1]
    batch_shape = A.shape[:-2]
    batch = 1
    for d in batch_shape:
        batch *= d

    # The Francis QR kernel runs in float32; eigenvalues/vectors are complex64.
    A_work = A.reshape(batch, n, n).to(torch.float32).contiguous()

    lr = torch.empty(batch, n, dtype=torch.float32, device=A.device)
    li = torch.empty(batch, n, dtype=torch.float32, device=A.device)
    vr = torch.empty(batch, n, n, dtype=torch.float32, device=A.device)
    vi = torch.empty(batch, n, n, dtype=torch.float32, device=A.device)

    BLOCK = triton.next_power_of_2(n)
    maxit = 100 * n + 100

    with torch.no_grad():
        _eig_kernel[(batch,)](A_work, lr, li, vr, vi, n, maxit, BLOCK=BLOCK)

    eigvals = torch.complex(lr, li).reshape(*batch_shape, n)
    eigvecs = torch.complex(vr, vi).reshape(*batch_shape, n, n)
    return eigvals, eigvecs
